// chamfer: a 30 × 20 × 10 block with a pocket of a sphere (radius 6) centred 2 above its top: the rim chamfered 1 mm
export function c005(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(30, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    opSphere(context, id + "ball", { "center" : vector(15, 10, 12) * millimeter, "radius" : 6 * millimeter });
    booleanBodies(context, id + "pocket", { "tools" : qBodyType(qCreatedBy(id + "ball", EntityType.BODY), BodyType.SOLID), "targets" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "operationType" : BooleanOperationType.SUBTRACTION });
    chamfer(context, id + "chamfer1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(20.656854, 10, 10) * millimeter), "chamferType" : ChamferType.EQUAL_OFFSETS, "width" : 1 * millimeter });
    return { "chamfer" : chamferProbe(context, qCreatedBy(id + "chamfer1", EntityType.FACE)) };
